// Original work by the same author.
import { err, ok, type Result } from "@zedtech/zedkit-core";
import { HEADER_KEYS } from "./agent-header.js";

/** Start of the marker on line 2 of every generated file; `sync` regenerates only files that carry it. */
export const MARKER_PREFIX = "# generated by zedkit-ai sync from ";

export function markerLine(name: string): string {
  return `${MARKER_PREFIX}.agents/agents/${name}.md and .agents/tokenomics.md; do not edit, run: npx zedkit-ai sync`;
}

/** True when line 2 is a sync marker (line 1 stays `---`, so the file is valid for every loader). */
export function hasMarker(text: string): boolean {
  const lines = text.split("\n", 3);
  return lines[0] === "---" && (lines[1] ?? "").startsWith(MARKER_PREFIX);
}

export type GenerateInput = {
  /** Agent name (the file name without `.md`). */
  name: string;
  /** The source file text from `.agents/agents`. */
  source: string;
  /** The model the route resolved for this provider; `inherit` means "the session's model". */
  model: string;
  /**
   * Cursor only: `readonly: true` is the write gate this tool enforces.
   * Never set on a Muse file (unknown key drops the agent) or in canonical
   * unmarked sources (validate rejects it as not portable).
   */
  readonly?: boolean;
  /** Muse aliases: marker cites this source name when it differs from `name`. */
  sourceName?: string;
};

export type Generated = { text: string; notes: string[] };

// A scalar both Cursor and Claude read back unchanged: no quotes, no spaces.
const PLAIN_MODEL = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const KEY_LINE = /^([A-Za-z_][A-Za-z0-9_-]*)[ \t]*:/;
const DROPPED: ReadonlySet<string> = new Set(HEADER_KEYS);

type Block = { key: string | undefined; lines: string[] };

// Frontmatter lines grouped per top-level key: a key line plus every line
// after it up to the next key line (nested maps, lists, comments).
function blocks(lines: readonly string[]): Block[] {
  const out: Block[] = [];
  for (const line of lines) {
    const key = KEY_LINE.exec(line)?.[1];
    if (key !== undefined || out.length === 0) out.push({ key, lines: [line] });
    else out[out.length - 1]?.lines.push(line);
  }
  return out;
}

function scalar(block: Block): string {
  return (block.lines[0] ?? "").replace(KEY_LINE, "").trim();
}

/**
 * The tool's copy of an agent: the source with the header blocks removed,
 * `model` set from the route, and the marker on line 2. It splices the
 * frontmatter as text and copies the body byte for byte, so a YAML library
 * upgrade cannot change how `description` is quoted. Pure: the same input
 * gives the same bytes. A `model` the source pins to anything other than
 * `inherit` is the author's choice and is kept as written.
 */
export function generateAgent(input: GenerateInput): Result<Generated> {
  const lines = input.source.replace(/\r\n/g, "\n").replace(/^\uFEFF/, "").split("\n");
  if (lines[0] !== "---") return err(new Error(`${input.name}: missing frontmatter (file must start with ---)`));
  const close = lines.findIndex((line, i) => i > 0 && line.trimEnd() === "---");
  if (close < 0) return err(new Error(`${input.name}: frontmatter is not closed`));
  if (input.model !== "inherit" && !PLAIN_MODEL.test(input.model)) {
    return err(new Error(`${input.name}: model "${input.model}" cannot be written as a plain value (letters, digits, . _ -)`));
  }

  const notes: string[] = [];
  const kept = blocks(lines.slice(1, close).filter((line) => !line.startsWith(MARKER_PREFIX))).filter(
    (block) => block.key === undefined || !DROPPED.has(block.key),
  );
  const at = kept.findIndex((block) => block.key === "model");
  if (at >= 0) {
    const current = scalar(kept[at] as Block);
    if (current === "inherit" || current === "") {
      kept[at] = { key: "model", lines: [`model: ${input.model}`] };
    } else {
      notes.push(`model pinned in source (${current}): route not applied`);
    }
  } else if (input.model !== "inherit") {
    kept.push({ key: "model", lines: [`model: ${input.model}`] });
  }
  if (input.readonly === true) {
    const readAt = kept.findIndex((block) => block.key === "readonly");
    if (readAt >= 0) kept[readAt] = { key: "readonly", lines: ["readonly: true"] };
    else kept.push({ key: "readonly", lines: ["readonly: true"] });
  }

  const frontmatter = kept.flatMap((block) => block.lines);
  const text = ["---", markerLine(input.name), ...frontmatter, ...lines.slice(close)].join("\n");
  return ok({ text, notes });
}

/** Muse 1.4.14 lists only names that match this; digits / `_` / capitals drop the agent. */
export const MUSE_AGENT_NAME = /^[a-z]+(-[a-z]+)*$/;

/** Kit names Muse drops silently; dest file and frontmatter use the alias. Cursor keeps the source name. */
export const MUSE_NAME_ALIAS: Readonly<Record<string, string>> = {
  "a11y-auditor": "accessibility-auditor",
};

/**
 * Frozen Muse dest name. Installer: `const dest = museNativeName(sourceName)`; then
 * `generateMuseAgent({ name: dest, sourceName, source, model })`. `undefined` means the
 * name is illegal on Muse 1.4.14 and has no map row: label a limitation, do not call
 * the Muse kit complete. Cursor/Claude keep generating from `sourceName`.
 */
export function museNativeName(name: string): string | undefined {
  if (MUSE_AGENT_NAME.test(name)) return name;
  return MUSE_NAME_ALIAS[name];
}

const MUSE_DEST_SOURCE: Readonly<Record<string, string>> = Object.fromEntries(
  Object.entries(MUSE_NAME_ALIAS).map(([source, dest]) => [dest, source]),
);

/**
 * Kit source name for a Muse dest (or any legal name). Table reverse only:
 * do not treat a dest as that source without `museIdentityName` provenance.
 */
export function museSourceName(name: string): string {
  return MUSE_DEST_SOURCE[name] ?? name;
}

/** Source name cited on a generated marker line, if this text is marked. */
export function markerSource(text: string): string | undefined {
  if (!hasMarker(text)) return undefined;
  const line = text.split("\n", 2)[1] ?? "";
  const match = /from \.agents\/agents\/([a-z0-9]+(?:-[a-z0-9]+)*)\.md /.exec(line);
  return match?.[1];
}

export type MuseAliasContext = {
  /** Unmarked source names on disk. Do not list reserved dests here. */
  sources: ReadonlySet<string>;
  /** File text at `name.md` when that path exists. */
  destText?: string;
};

/**
 * Dest is reserved Muse output of a kit source only with provenance: a marker
 * citing that source, or a present unmarked source while dest is absent/marked.
 * An unmarked dest is a user homonym — never reserved, even if the source exists.
 * Installer: skip dest as a Cursor/Claude source only when this is true.
 */
export function isReservedMuseDest(name: string, ctx: MuseAliasContext): boolean {
  const source = MUSE_DEST_SOURCE[name];
  if (source === undefined) return false;
  if (ctx.destText !== undefined && !hasMarker(ctx.destText)) return false;
  if (ctx.destText !== undefined && markerSource(ctx.destText) === source) return true;
  return ctx.sources.has(source);
}

/**
 * Header identity for route/delegation. Reserved Muse dest → kit source CHECK
 * rights; unmarked dest → itself (legitimate homonym).
 */
export function museIdentityName(name: string, ctx: MuseAliasContext): string {
  const source = MUSE_DEST_SOURCE[name];
  if (source === undefined) return name;
  return isReservedMuseDest(name, ctx) ? source : name;
}

const MUSE_KEYS = new Set(["name", "description", "model", "disallowedTools"]);
const MUSE_DENIED: Readonly<Record<string, string>> = {
  Write: "write_file",
  Edit: "edit_file",
};

/**
 * Muse write-capable tools `disallowedTools` actually enforces (Muse 1.4.14).
 * orch-88 observed /tmp bash writes; P8 wrote a project-relative
 * `./probe-zk-w-a-shell.txt` with default sandbox ON. That is a tool-restriction
 * hole, not a sandbox-allowed temp write. `write_file, edit_file` alone is
 * the unsafe skip. Adding `bash` is the fail-closed policy: native 1010 spawn
 * in an isolated probe (`zk-closed`) left `./probe-zk-closed-1010.txt` absent;
 * child reported `read=ok edit=no-tool shell=no-tool` and quoted README via
 * `read_file`. Muse has no write-vs-read bash split — check agents lose the
 * executor; `read_file`/`search` stay. Writers without `disallowedTools` keep
 * bash.
 */
export const MUSE_WRITE_TOOLS = ["write_file", "edit_file", "bash"] as const;

function museDenied(value: string): string | undefined {
  const names: string[] = [];
  const seen = new Set<string>();
  let writes = false;
  for (const part of value.split(",").map((item) => item.trim()).filter(Boolean)) {
    const mapped = MUSE_DENIED[part] ?? ((MUSE_WRITE_TOOLS as readonly string[]).includes(part) ? part : "");
    if (mapped === "") continue;
    writes = true;
    if (seen.has(mapped)) continue;
    seen.add(mapped);
    names.push(mapped);
  }
  if (!writes) return undefined;
  for (const tool of MUSE_WRITE_TOOLS) {
    if (seen.has(tool)) continue;
    seen.add(tool);
    names.push(tool);
  }
  return names.join(", ");
}

/**
 * Muse-native agent file: closed frontmatter (unknown keys drop the agent),
 * Muse tool names in `disallowedTools` (Write/Edit → write_file, edit_file, bash),
 * route baked into `model`, marker on line 2, body copied byte for byte. Not a
 * generic source: Cursor/Claude must keep generating from the unmarked/kit file,
 * never from this output.
 */
export function generateMuseAgent(input: GenerateInput): Result<Generated> {
  const lines = input.source.replace(/\r\n/g, "\n").replace(/^\uFEFF/, "").split("\n");
  if (lines[0] !== "---") return err(new Error(`${input.name}: missing frontmatter (file must start with ---)`));
  const close = lines.findIndex((line, i) => i > 0 && line.trimEnd() === "---");
  if (close < 0) return err(new Error(`${input.name}: frontmatter is not closed`));
  if (input.model !== "inherit" && !PLAIN_MODEL.test(input.model)) {
    return err(new Error(`${input.name}: model "${input.model}" cannot be written as a plain value (letters, digits, . _ -)`));
  }

  const notes: string[] = [];
  const kept: Block[] = [];
  for (const block of blocks(lines.slice(1, close).filter((line) => !line.startsWith(MARKER_PREFIX)))) {
    if (block.key === undefined) {
      kept.push(block);
      continue;
    }
    if (!MUSE_KEYS.has(block.key)) continue;
    if (block.key === "name") {
      kept.push({ key: "name", lines: [`name: ${input.name}`] });
      continue;
    }
    if (block.key === "disallowedTools") {
      const mapped = museDenied(scalar(block));
      if (mapped === undefined) continue;
      kept.push({ key: "disallowedTools", lines: [`disallowedTools: ${mapped}`] });
      continue;
    }
    kept.push(block);
  }
  const at = kept.findIndex((block) => block.key === "model");
  if (at >= 0) {
    const current = scalar(kept[at] as Block);
    if (current === "inherit" || current === "") {
      kept[at] = { key: "model", lines: [`model: ${input.model}`] };
    } else {
      notes.push(`model pinned in source (${current}): route not applied`);
    }
  } else if (input.model !== "inherit") {
    kept.push({ key: "model", lines: [`model: ${input.model}`] });
  }

  const frontmatter = kept.flatMap((block) => block.lines);
  const text = ["---", markerLine(input.sourceName ?? input.name), ...frontmatter, ...lines.slice(close)].join("\n");
  return ok({ text, notes });
}
